import Mathlib.Data.Matrix.Basic
import Mathlib.Algebra.BigOperators.Group.Finset

variable {R : Type*} [CommRing R] {n : ℕ}

def CyclicProduct (A : Matrix (Fin n) (Fin n) R) {k : ℕ} (ι : Fin k ↪ Fin n) : R :=
  ∏ j : Fin k, A (ι j) (ι (j + 1))

def Strongly1Principled (A : Matrix (Fin n) (Fin n) R) : Prop :=
  (∀ i : Fin n, A i i = 1) ∧
  (∀ k : ℕ, ∀ ι : Fin k ↪ Fin n, k > 1 → CyclicProduct A ι = 0)

theorem power_strongly_1_principled (A : Matrix (Fin n) (Fin n) R) (m : ℕ)
  (hA : Strongly1Principled A) : Strongly1Principled (A ^ m) := by sorry
